{
 if(a<b)
 return a;
 return b;
}
int minimum_time_required(int reach[][3],int spent[][4], int *entry, int *exit, int n)
{
 int t1[n], t2[n], i;
 t1[0] = entry[0] + spent[0][0];
 t2[0] = entry[1] + spent[1][0];
 for(i = 1; i < n; i++)
 {
