What is the output of the following code? 
#include<stdio.h>
#include<string.h>
int max(int a, int b)
{
 if(a > b)
 return a;
 return b;
}
int min_ins(char *s)
{
 int len = strlen(s), i, j;
 int arr[len + 1][len + 1];
 char rev[len + 1];
 strcpy(rev, s);
 strrev(rev);
 for(i = 0;i <= len; i++)
 arr[i][0] = 0;
 for(i = 0; i <= len; i++)
 arr[0][i] = 0;
 for(i = 1; i <= len; i++)
 {
 for(j = 1; j <= len; j++)
 {
 if(s[i - 1] == rev[j - 1])
 arr[i][j] = arr[i - 1][j - 1] + 1;
 else
 arr[i][j] = max(arr[i - 1][j], arr[i][j - 1]);
 }
 }
 return len - arr[len][len];
}
int main()
{
 char s[] = "abcda";
 int ans = min_ins(s);
 printf("%d",ans);
 return 0;
}

