Consider the following implementation of Kadane's algorithm: 
#include<stdio.h>
int max_num(int a, int b)
{
 if(a > b)
 return a;
 return b;
}
int kadane_algo(int *arr, int len) 
{
 int ans = 0, sum = 0, idx;
 for(idx =0; idx < len; idx++)
 {
 sum = max_num(0,sum + arr[idx]);
 ans = max_num(sum,ans);
 }
 return ans;
}
