int max_num(int a,int b)
{
 if(a> b)
 return a;
 return b;
}
int maximum_subarray_sum(int *arr, int len)
{
 int sum[len], idx;
 sum[0] = arr[0];
 for(idx = 1; idx < len; idx++)
 sum[idx] = max_num(sum[idx - 1] + arr[idx], arr[idx]);
 int mx = sum[0];
 for(idx = 0; idx < len; idx++)
 if(sum[idx] > mx)
 mx =sum[idx];
 return mx;
}
